function seriesName(w,row,group){const mixed=new Set(w.rows.filter(r=>!ratio(w.type,r)).map(r=>currency(w.type,r))).size>1;return ctx.label(w.type,row)+(w.groups.length>1?' · '+groups[group]:'')+(mixed?' · '+currency(w.type,row):'');}
