function chartContext(w){const r=ratio(w.type,w.rows[0]),units=[...new Set(w.rows.filter(id=>!ratio(w.type,id)).map(id=>currency(w.type,id)))],measure=hybrid(w)&&w.mode==='change'?'QoQ / MoM':w.mode==='nominal'?(r?'Oran':w.type==='PL'&&w.basis==='cumulative'?'Kümülatif':'Hacim'):w.mode==='ytdChange'&&w.type==='PL'?'YTD YoY':modes[w.mode];return w.groups.map(g=>groups[g]).join(' / ')+' · '+measure+' · '+suffix(w,w.mode,r)+(w.mode!=='nominal'&&!r?' · '+units.join(' / '):'')+' · '+(w.start===w.end?periodText(w,w.start+'-01',true):periodText(w,w.start+'-01',true)+' – '+periodText(w,w.end+'-01',true))+(hybrid(w)?' · Tam çeyrek + açık çeyrek ayları':'')+(w.kind==='pie'?' · Son ay':'');}
