function chartNumberCode(w,percent=false){const unit=labelSuffix(w);return '[$-409]'+(percent?'0':'#,##0')+(precision(w)?'.'+'0'.repeat(precision(w)):'')+(percent?'%':unit?'"'+unit+'"':'');}
function format(v){return E.finite(v)?nf.format(v):'—';}
