   const url=URL.createObjectURL(new Blob([new XMLSerializer().serializeToString(clone)],{type:'image/svg+xml'}));try{const img=await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(Error('Grafik PDF için çizilemedi.'));img.src=url;});g.drawImage(img,b.x,b.y,b.w,b.h);}finally{URL.revokeObjectURL(url);}
